  return (
    <div className="page-404">
      <div style={{ fontSize: 80, marginBottom: 20 }}>🍱</div>
      <h1 style={{ fontSize: 28, fontWeight: 800, color: '#111827', marginBottom: 10 }}>Page not found</h1>
